+const UNDO_MS = 6000;
+
+export function ArchiveUndoToast({
+  title,
+  onUndo,
+  onDismiss,
+}: {
+  title: string;
+  onUndo: () => void;
+  onDismiss: () => void;
+}) {
+  useEffect(() => {
+    const timer = window.setTimeout(onDismiss, UNDO_MS);
+    return () => window.clearTimeout(timer);
+  }, [onDismiss]);
+
+  return createPortal(
+    <div
+      role="status"
+      style={{ zIndex: LAYER.toast, background: "var(--color-background-base)" }}
+      className="fixed bottom-4 left-1/2 flex max-w-[min(420px,calc(100vw-24px))] -translate-x-1/2 items-center gap-3 rounded-lg border border-content/10 px-3 py-2 text-[13px] text-content shadow-lg"
