+      <span className="min-w-0 truncate">Archived {title}</span>
+      <button
+        type="button"
+        className="shrink-0 font-medium text-accent"
+        onClick={onUndo}
+      >
+        Undo
+      </button>
+    </div>,
+    document.body,
+  );
+}
